// ServerInterface represents all server handlers.
type ServerInterface interface {
	// CreateCommunityProduct Mint a community product from an approved submission (role admin)
	// (POST /admin/products)
	CreateCommunityProduct(w http.ResponseWriter, r *http.Request)
	// ListCommunityProducts List community products, un-promoted only (role admin)
	// (GET /admin/products/community)
	ListCommunityProducts(w http.ResponseWriter, r *http.Request, params ListCommunityProductsParams)
	// ListPromoteCandidates Community products with plausible provider matches (role admin)
	// (GET /admin/products/promote-candidates)
	ListPromoteCandidates(w http.ResponseWriter, r *http.Request, params ListPromoteCandidatesParams)
	// ListUnmatchedProducts List unmatched products, admin-held included (role admin)
	// (GET /admin/products/unmatched)
	ListUnmatchedProducts(w http.ResponseWriter, r *http.Request, params ListUnmatchedProductsParams)
	// DeleteProduct Delete an unmatched product and its snapshots (role admin)
	// (DELETE /admin/products/{productId})
	DeleteProduct(w http.ResponseWriter, r *http.Request, productId openapi_types.UUID)
	// SetProductMapping Correct a product's PriceCharting mapping and mark it verified (role admin)
	// (PUT /admin/products/{productId}/pricecharting)
	SetProductMapping(w http.ResponseWriter, r *http.Request, productId openapi_types.UUID)
	// PromoteProduct Promote a community product to provider identity in place (role admin)
	// (POST /admin/products/{productId}/promote)
	PromoteProduct(w http.ResponseWriter, r *http.Request, productId openapi_types.UUID)
	// DismissPromoteCandidate Dismiss one promote candidate permanently (role admin)
	// (POST /admin/products/{productId}/promote-candidates/dismiss)
	DismissPromoteCandidate(w http.ResponseWriter, r *http.Request, productId openapi_types.UUID)
	// TriggerRefresh Trigger an immediate catalog refresh (role admin)
	// (POST /admin/refresh)
	TriggerRefresh(w http.ResponseWriter, r *http.Request)
	// GetFxLatest Latest USD-based exchange rates (cached daily snapshot)
	// (GET /fx/latest)
	GetFxLatest(w http.ResponseWriter, r *http.Request)
	// InternalNormalizeCommunityRegions Promote free-text community product regions into the known set
	// (POST /internal/normalize-community-regions)
	InternalNormalizeCommunityRegions(w http.ResponseWriter, r *http.Request)
	// InternalRefresh Catalog refresh trigger (CronJob)
	// (POST /internal/refresh)
	InternalRefresh(w http.ResponseWriter, r *http.Request)
	// ListPlatforms The canonical platform catalog with alias knowledge
	// (GET /platforms)
	ListPlatforms(w http.ResponseWriter, r *http.Request)
	// BatchPriceHistory Price snapshot series for a set of products (value-over-time composition)
	// (POST /products/price-history:batch)
	BatchPriceHistory(w http.ResponseWriter, r *http.Request)
	// BatchPrices Current prices for a set of products (dashboard composition)
	// (POST /products/prices:batch)
	BatchPrices(w http.ResponseWriter, r *http.Request)
	// ResolveProduct Find-or-create the canonical product for a search selection
	// (POST /products/resolve)
	ResolveProduct(w http.ResponseWriter, r *http.Request)
	// GetProduct Fetch a product (read-through with per-type staleness)
	// (GET /products/{productId})
	GetProduct(w http.ResponseWriter, r *http.Request, productId openapi_types.UUID)
	// ScoreRecommendations Score unowned games against a library summary (user-agnostic)
	// (POST /recommendations:score)
	ScoreRecommendations(w http.ResponseWriter, r *http.Request)
	// SearchCatalog Discovery search (game metadata via IGDB, hardware via PriceCharting)
	// (GET /search)
	SearchCatalog(w http.ResponseWriter, r *http.Request, params SearchCatalogParams)
}

